use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 { continue }
        let cmd = p[0]
        if cmd == "balance" {
            if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                println("${acc[p[1]]}")
            }
        } else if cmd == "open" {
            let amt: int = p[2].parse().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                acc.insert(p[1], amt)
                println("ok")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let amt: int = p[2].parse().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let b = acc[p[1]]
                if cmd == "deposit" {
                    acc.insert(p[1], b + amt)
                    println("ok")
                } else if amt > b {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], b - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" {
            let amt: int = p[3].parse().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else if !acc.contains_key(p[2]) {
                println("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let a = acc[p[1]]
                let b = acc[p[2]]
                if amt > a {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], a - amt)
                    acc.insert(p[2], b + amt)
                    println("ok")
                }
            }
        }
    }
    let mut keys: Vec<string> = []
    for k in acc.keys() { keys.push(k) }
    keys.sort()
    for k in keys {
        println("${k} ${acc[k]}")
    }
}

